/* @lc app=leetcode id=1681 lang=kotlin */
class Solution {
    fun minimumIncompatibility(nums: IntArray, k: Int): Int = nums.sorted().let { s -> (s.size / k).let { sz -> if (s.groupingBy { it }.eachCount().any { it.value > k }) -1 else (1 shl s.size).let { mSize -> (0 until mSize).filter { java.lang.Integer.bitCount(it) == sz }.filter { m -> (0 until s.size).filter { (m and (1 shl it)) != 0 }.map { s[it] }.let { chunk -> (1 until chunk.size).all { chunk[it] != chunk[it-1] } } }.let { validMasks -> IntArray(mSize) { 1000000 }.apply { this[0] = 0 }.also { dp -> (0 until mSize).forEach { m -> if (dp[m] < 1000000) (0 until s.size).firstOrNull { (m and (1 shl it)) == 0 }?.let { first -> validMasks.forEach { sub -> if ((sub and (1 shl first)) != 0 && (sub and m) == 0) (0 until s.size).filter { (sub and (1 shl it)) != 0 }.map { s[it] }.let { chunk -> dp[m or sub] = minOf(dp[m or sub], dp[m] + chunk.last() - chunk.first()) } } } } } }.let { if (it.last() >= 1000000) -1 else it.last() } } } }
}